action.code:
if (!root) {
    root = new TreeNode;
    root->value = item;
    root->left = nullptr;
    root->right = nullptr;
    root->bFactor = 0;
    return;
}

if (item < root->value) {
    avlInsert(root->left, item);
} else {
    avlInsert(root->right, item);
}

root->bFactor = _height(root->left) - _height(root->right);

if (root->bFactor > 1) {
    if (item < root->left->value) {
        _rotateRight(root);
    } else {
        _rotateLeft(root->left);
        _rotateRight(root);
    }
} else if (root->bFactor < -1) {
    if (item > root->right->value) {
        _rotateLeft(root);
    } else {
        _rotateRight(root->right);
        _rotateLeft(root);
    }
}

